const migrationPaths=fs.readdirSync(path.join(workspace,'backend/internal/db/migrations')).filter(p=>p.endsWith('.sql')).sort().map(p=>'backend/internal/db/migrations/'+p);
const inventoryPath='docs/system-backup-restore-schema-inventory.json',inventory=JSON.parse(read(inventoryPath));
const missing=['system_backup_catalog_imports','system_backup_catalog_records','system_backup_catalog_scan_states'];assert.deepEqual(inventory.gaps.plan_control_without_inventory,missing);
const evidenceForeignKeys=[],catalogSourceDeclarations=[],createdTables=[];
for(const p of migrationPaths){
  let table=null;
  for(const [index,line] of read(p).split('\n').entries()){
    const created=line.match(/^CREATE TABLE(?: IF NOT EXISTS)?\s+`?([a-z_0-9]+)`?\s*\(/i);
    if(created){table=created[1];createdTables.push({table,path:p,line:index+1});}
    if(/FOREIGN KEY.*REFERENCES system_backup_evidence\(/i.test(line)){
      assert.ok(table);const name=line.match(/CONSTRAINT\s+(\w+)\s+FOREIGN KEY/)[1];
      evidenceForeignKeys.push({table,constraint:name,path:p,line:index+1,statement:line.trim(),target:'retained_evidence_envelope',automatic_metadata_gc_blocker:false,disposition:'Trace the real lifecycle and any link to the original operation/audits/nonce; this declaration alone neither allows nor blocks deleting the download group.'});
    }
    if(/source_artifact_type ENUM\(.+catalog_import/.test(line)){assert.ok(table);catalogSourceDeclarations.push({table,path:p,line:index+1,statement:line.trim()});}
  }
}
assert.equal(evidenceForeignKeys.length,11);assert.equal(catalogSourceDeclarations.length,5);
for(const name of missing){assert.ok(!createdTables.some(r=>r.table===name));assert.ok(!inventory.objects.some(r=>r.name===name));}
